const FAQ_DATA = [
  {
    id: 'purring',
    question: "Why do cats purr?",
    answer: "Cats purr for many reasons! While it usually means they are happy and relaxed, they also purr to soothe themselves when stressed or in pain. Some scientists believe the frequency of a cat's purr can even help improve bone density and promote healing."
  },
  {
    id: 'kneading',
    question: "Why do cats 'make biscuits' (knead)?",
    answer: "Kneading is a behavior cats carry over from kittenhood, where they knead their mother to stimulate milk flow. In adults, it's a sign of extreme comfort, contentment, and a way to mark their territory with scent glands in their paws."
  },
  {
    id: 'eyes',
    question: "Can cats really see in the dark?",
    answer: "Cats can't see in total darkness, but they are much better at it than humans. They only need about one-sixth of the light we do. This is thanks to the tapetum lucidum, a reflective layer behind their retina that gives their eyes that spooky glow at night."
  },
  {
    id: 'tongue',
    question: "Why are cats' tongues so rough?",
    answer: "A cat's tongue is covered in tiny, hook-like structures called papillae. These are made of keratin (just like your fingernails) and act like a natural hairbrush for grooming and help them grip food more effectively."
  },
  {
    id: 'sleep',
    question: "Why do cats sleep so much?",
    answer: "Cats are crepuscular predators, meaning they are most active at dawn and dusk. They spend 12 to 16 hours a day sleeping to conserve energy for those short, intense bursts of hunting (or chasing laser pointers)."
  }
];

const FAQItem = ({ item }) => {
  const [isOpen, setIsOpen] = useState(false);
  const contentId = `details-${item.id}`;

  return (
    <div className="example">
      <button
        id={`btn-${item.id}`}
        type="button"
        className="faq-button"
        aria-expanded={isOpen}
        aria-controls={contentId}
        onClick={() => setIsOpen(!isOpen)}
      >
        <span>{item.question}</span>
        <svg
          className="faq-icon"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
          xmlns="http://www.w3.org/2000/svg"
          aria-hidden="true"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M19 9l-7 7-7-7"
          />
        </svg>
      </button>
      <div
        id={contentId}
        className="details"
        role="region"
        aria-labelledby={`btn-${item.id}`}
      >
        <div className="details-content">
          <p>{item.answer}</p>
        </div>
      </div>
    </div>
  );
};

const App = () => {
  return (
    <div className="container">
      <header>
        <h1>Feline Frequently Asked Questions</h1>
      </header>
      <main id="main">
        <div className="faq-list">
          {FAQ_DATA.map((item) => (
            <FAQItem key={item.id} item={item} />
          ))}
        </div>
      </main>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
