  max-width: 600px;
}

h1 {
  font-size: 2.25rem;
  font-weight: 800;
  text-align: center;
  margin-bottom: 2rem;
  color: var(--text-main);
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Requirement: Wrap each question/answer in div.example */
.example {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.example:hover {
  box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1);
}

.faq-button {
  width: 100%;
  text-align: left;
  padding: 1.25rem;
  background: none;
  border: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-main);
}

.faq-button:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: -2px;
}

.faq-icon {
  width: 1.25rem;
  height: 1.25rem;
  transition: transform 0.3s ease;
  color: var(--text-muted);
}

.faq-button[aria-expanded="true"] .faq-icon {
  transform: rotate(180deg);
}

/* Requirement: Container for controlled content class "details" */
.details {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out, padding 0.3s ease;
  background-color: #fdfdfd;
}

.faq-button[aria-expanded="true"] + .details {
  max-height: 500px; /* Arbitrary large enough value */
  border-top: 1px solid var(--border-color);
}

.details-content {
  padding: 1.25rem;
  color: var(--text-muted);
}

@media (prefers-reduced-motion: reduce) {
  .faq-icon, .details {
    transition: none;
  }
}
